{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Capture Meeting Content",
        "actor": "Minute Taker",
        "system": "Calendar System / Meeting Notes or Transcript",
        "inputs": ["Meeting agenda", "Meeting transcripts or notes", "Calendar entry with participant list"],
        "outputs": ["Raw meeting notes or transcript"]
      },
      {
        "id": "A2",
        "name": "Clarify Unclear Items with Decision Owners",
        "actor": "Minute Taker",
        "system": "Email Client or direct communication (unspecified)",
        "inputs": ["Raw meeting notes or transcript", "List of unclear decisions or action items"],
        "outputs": ["Clarified decisions and action-item details"]
      },
      {
        "id": "A3",
        "name": "Draft Meeting Summary",
        "actor": "Minute Taker",
        "system": "Email Client (template-based)",
        "inputs": ["Raw meeting notes or transcript", "Clarified decisions and action-item details"],
        "outputs": ["Draft meeting summary including decisions made and action-item assignments with owners"]
      },
      {
        "id": "A4",
        "name": "Determine Email Recipient List",
        "actor": "Minute Taker",
        "system": "Calendar System / Email Client",
        "inputs": ["Participant list from meeting invite or notes"],
        "outputs": ["Email recipient list"]
      },
      {
        "id": "A5",
        "name": "Send Summary Email",
        "actor": "Minute Taker",
        "system": "Email Client",
        "inputs": ["Draft meeting summary", "Email recipient list"],
        "outputs": ["Sent summary email"]
      },
      {
        "id": "A6",
        "name": "Log Action Items in Task Tracker",
        "actor": "Minute Taker",
        "system": "Task Tracker",
        "inputs": ["Action-item assignments with owners and deadlines (where available)"],
        "outputs": ["Action items recorded in task tracker"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are there unclear decisions or action items in the raw notes?",
        "branches": [
          "Yes — proceed to A2 (Clarify Unclear Items with Decision Owners)",
          "No — proceed directly to A3 (Draft Meeting Summary)"
        ]
      },
      {
        "id": "D2",
        "condition": "Do any action items require follow-up tracking?",
