      {
        "id": "E2",
        "description": "Decision owners unavailable for clarification — unclear items cannot be resolved before drafting",
        "handling": "Not specified; may result in incomplete or inaccurate summary"
      },
      {
        "id": "E3",
        "description": "Missing or incomplete meeting notes or transcript — insufficient input for summary drafting",
        "handling": "Not specified"
